# 动态规划进阶
## 1. 二维 DP
二维 DP 是两个维度上的状态转移，常见于字符串匹配、路径问题。
### 要点
- dp[i][j] 通常表示两个序列的前 i 和前 j 个元素的某种关系
- 常见场景：LCS、编辑距离、不同路径
- 遍历顺序：通常外层 i，内层 j
### 示例/代码
// 不同路径 (LeetCode 62)
// dp[i][j] = 从 (0,0) 到 (i,j) 的路径数
public int uniquePaths(int m, int n) {
int[][] dp = new int[m][n];
for (int i = 0; i < m; i++) dp[i][0] = 1;
for (int j = 0; j < n; j++) dp[0][j] = 1;
for (int i = 1; i < m; i++) {
for (int j = 1; j < n; j++) {
dp[i][j] = dp[i-1][j] + dp[i][j-1];
}

// 不同路径 (LeetCode 62)
// dp[i][j] = 从 (0,0) 到 (i,j) 的路径数
public int uniquePaths(int m, int n) {
int[][] dp = new int[m][n];
for (int i = 0;
i < m;
i++) dp[i][0] = 1;
for (int j = 0;
j < n;
j++) dp[0][j] = 1;
for (int i = 1;
i < m;
i++) {
for (int j = 1;
j < n;
j++) {
dp[i][j] = dp[i-1][j] + dp[i][j-1];
}
}
return dp[m-1][n-1];
}
